namespace sv_225bc71b5ead444abd531408973786ea.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_225bc71b5ead444abd531408973786ea.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
                    @_toastMessage
                    <button class="btn-close btn-close-sm ms-2" @onclick="() => _toastMessage = null"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@* ───── Profile Section ───── *@

@{ RenderFragment RenderProfile() =>
    @<section class="settings-section">
        <h3>Profile</h3>
        <p class="text-muted">Manage your public profile information.</p>
        <hr />

        <div class="avatar-area mb-4">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_profileDisplayName))
                {
                    <img src="@_profileAvatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">?</div>
                }
            </div>
            <div class="avatar-url-display">
                <small class="text-muted">Avatar URL:</small>
                <code>@_profileAvatarUrl</code>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_profileDisplayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_profileEmail" />
        </div>
        <div class="mb-3">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" @bind="_profileAvatarUrl" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </section>;
}

@* ───── Notifications Section ───── *@

@{ RenderFragment RenderNotifications() =>
    @<section class="settings-section">
        <h3>Notifications</h3>
        <p class="text-muted">Choose how you want to be notified.</p>
        <hr />

        <div class="toggle-row">
            <div>
                <strong>Email Notifications</strong>
                <div class="text-muted small">Receive notifications via email</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifEmail" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Push Notifications</strong>
                <div class="text-muted small">Receive push notifications in your browser</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifPush" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Weekly Digest</strong>
                <div class="text-muted small">Get a weekly summary of activity</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifWeeklyDigest" />
            </div>
        </div>

        <h5 class="mt-4 mb-3">Muted Channels</h5>
        @if (_allChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMuteChannel(ch, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                    </div>
                }
            </div>
        }

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>
    </section>;
}

@* ───── Security Section ───── *@

@{ RenderFragment RenderSecurity() =>
    @<section class="settings-section">
        <h3>Security</h3>
        <p class="text-muted">Manage your account security settings.</p>
        <hr />

        @* Change Password Panel *@
        <div class="expandable-panel mb-4">
            <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="expandable-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger py-2">@_passwordError</div>
                    }
                    <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Update Password
                    </button>
                </div>
            }
        </div>

        @* Two-Factor Auth *@
        <div class="toggle-row">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">
                    Status:
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_twoFactorEnabled" />
            </div>
        </div>

        @if (_securitySettings?.LastPasswordChange is not null)
        {
            <p class="text-muted small mt-2">
                Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        @* Active Sessions *@
        <h5 class="mt-4 mb-3">Active Sessions</h5>
        @if (_sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }

        @* Revoke Confirmation Dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop-custom" @onclick="() => _sessionToRevoke = null"></div>
            <div class="confirm-dialog">
                <h5>Revoke Session</h5>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="d-flex gap-2 justify-content-end">
                    <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Revoke
                    </button>
                </div>
            </div>
        }
    </section>;
}

@* ───── Appearance Section ───── *@

@{ RenderFragment RenderAppearance() =>
    @<section class="settings-section">
        <h3>Appearance</h3>
        <p class="text-muted">Customize the look and feel of the application.</p>
        <hr />

        <div class="mb-4">
            <label class="form-label fw-bold">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    var t = theme;
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{t}")" value="@t"
                               checked="@(_appearanceTheme == t)"
                               @onchange="() => _appearanceTheme = t" />
                        <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var s = size;
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{s}")" value="@s"
                               checked="@(_appearanceFontSize == s)"
                               @onchange="() => _appearanceFontSize = s" />
                        <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold">Language</label>
            <select class="form-select" style="max-width: 300px;" @bind="_appearanceLanguage">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
                <option value="pt">Português</option>
            </select>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Compact Mode</strong>
                <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_appearanceCompact" />
            </div>
        </div>

        @* Live Preview *@
        <h5 class="mt-4 mb-3">Preview</h5>
        <div class="live-preview @GetPreviewClasses()">
            <div class="preview-header">Dashboard</div>
            <div class="preview-body">
                <p class="preview-text">This is a preview of your selected appearance settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Content renders with your chosen theme, font size, and compact mode preferences.</p>
                </div>
                <button class="preview-btn">Sample Button</button>
            </div>
        </div>

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>
    </section>;
}

@code {
    // ── Navigation ──
    private string ActiveSection { get; set; } = "profile";

    private readonly record struct SectionInfo(string Key, string Label, string Icon);
    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🛡️"),
        new("appearance", "Appearance", "🎨"),
    ];

    // ── Shared state ──
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;

    // ── Profile state ──
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";

    // ── Notification state ──
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = new();
    private readonly List<string> _allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    // ── Security state ──
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = new();
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _appearanceTheme = "System";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "en";
    private bool _appearanceCompact;

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        ApplyProfile(await profileTask);
        ApplyNotifications(await notifTask);
        ApplySecurity(await securityTask);
        ApplyAppearance(await appearanceTask);
    }

    // ── Profile ──

    private void ApplyProfile(UserProfile p)
    {
        _savedProfile = p;
        _profileDisplayName = p.DisplayName;
        _profileEmail = p.Email;
        _profileAvatarUrl = p.AvatarUrl;
        _profileBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save profile: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        ShowToast("Changes discarded.");
    }

    // ── Notifications ──

    private void ApplyNotifications(NotificationPrefs n)
    {
        _notifEmail = n.EmailNotifications;
        _notifPush = n.PushNotifications;
        _notifWeeklyDigest = n.WeeklyDigest;
        _mutedChannels = new List<string>(n.MutedChannels);
    }

    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save preferences: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Security ──

    private void ApplySecurity(SecuritySettings s)
    {
        _securitySettings = s;
        _twoFactorEnabled = s.TwoFactorEnabled;
        _sessions = new List<ActiveSession>(s.Sessions);
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally { _saving = false; }
    }

    private void PromptRevokeSession(ActiveSession session) => _sessionToRevoke = session;

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;

        _saving = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            ShowToast($"Session on {_sessionToRevoke.Device} revoked.");
            _sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to revoke session: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Appearance ──

    private void ApplyAppearance(AppearanceSettings a)
    {
        _appearanceTheme = a.Theme;
        _appearanceFontSize = a.FontSize;
        _appearanceLanguage = a.Language;
        _appearanceCompact = a.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appearanceTheme.ToLowerInvariant()} preview-font-{_appearanceFontSize.ToLowerInvariant()}";
        if (_appearanceCompact) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save appearance: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Toast ──

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

/* ── Layout ── */

.settings-dashboard {
    display: flex;
    min-height: 80vh;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.25rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
    font-weight: 600;
}

/* ── Toast ── */

.settings-toast {
    position: sticky;
    top: 0;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.65rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    font-size: 0.9rem;
    animation: slideDown 0.25s ease-out;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Avatar ── */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.25rem;
}

.avatar-preview img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: #adb5bd;
}

.avatar-url-display {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.avatar-url-display code {
    font-size: 0.8rem;
    word-break: break-all;
}

/* ── Toggle Rows ── */

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row .form-check-input {
    width: 2.5em;
    height: 1.25em;
}

/* ── Channel List ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    overflow: hidden;
}

.expandable-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
