}

.expandable-header:hover {
    background: #e9ecef;
}

.expandable-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* ── Confirm Dialog ── */

.modal-backdrop-custom {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1040;
}

.confirm-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
