/* ── Live Preview ── */

.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-card {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin: 0.75rem 0;
}

.preview-card p {
    margin-bottom: 0;
}

.preview-btn {
    padding: 0.35rem 1rem;
    border-radius: 4px;
    border: none;
    font-weight: 500;
    cursor: default;
}

/* Theme: Light */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}
.preview-theme-light .preview-header {
    background: #f8f9fa;
}
.preview-theme-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

/* Theme: Dark */
.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
}
.preview-theme-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}
.preview-theme-dark .preview-card {
    border-color: #45475a;
    background: #313244;
}
.preview-theme-dark .preview-btn {
    background: #89b4fa;
