@* ───── Security Section ───── *@

@{ RenderFragment RenderSecurity() =>
    @<section class="settings-section">
        <h3>Security</h3>
        <p class="text-muted">Manage your account security settings.</p>
        <hr />

        @* Change Password Panel *@
        <div class="expandable-panel mb-4">
            <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="expandable-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger py-2">@_passwordError</div>
                    }
                    <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Update Password
                    </button>
                </div>
            }
        </div>

        @* Two-Factor Auth *@
        <div class="toggle-row">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">
                    Status:
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_twoFactorEnabled" />
            </div>
        </div>

        @if (_securitySettings?.LastPasswordChange is not null)
        {
            <p class="text-muted small mt-2">
                Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        @* Active Sessions *@
        <h5 class="mt-4 mb-3">Active Sessions</h5>
        @if (_sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }

        @* Revoke Confirmation Dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop-custom" @onclick="() => _sessionToRevoke = null"></div>
            <div class="confirm-dialog">
                <h5>Revoke Session</h5>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="d-flex gap-2 justify-content-end">
                    <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Revoke
                    </button>
                </div>
            </div>
        }
    </section>;
}

