@code {
    // ── Navigation ──
    private string ActiveSection { get; set; } = "profile";

    private readonly record struct SectionInfo(string Key, string Label, string Icon);
    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🛡️"),
        new("appearance", "Appearance", "🎨"),
    ];

    // ── Shared state ──
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;

    // ── Profile state ──
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";

    // ── Notification state ──
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = new();
    private readonly List<string> _allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    // ── Security state ──
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = new();
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _appearanceTheme = "System";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "en";
    private bool _appearanceCompact;

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        ApplyProfile(await profileTask);
        ApplyNotifications(await notifTask);
        ApplySecurity(await securityTask);
        ApplyAppearance(await appearanceTask);
    }

    // ── Profile ──

    private void ApplyProfile(UserProfile p)
    {
        _savedProfile = p;
        _profileDisplayName = p.DisplayName;
        _profileEmail = p.Email;
        _profileAvatarUrl = p.AvatarUrl;
        _profileBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save profile: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        ShowToast("Changes discarded.");
    }

    // ── Notifications ──

    private void ApplyNotifications(NotificationPrefs n)
    {
        _notifEmail = n.EmailNotifications;
        _notifPush = n.PushNotifications;
        _notifWeeklyDigest = n.WeeklyDigest;
        _mutedChannels = new List<string>(n.MutedChannels);
    }

    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save preferences: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Security ──

    private void ApplySecurity(SecuritySettings s)
    {
        _securitySettings = s;
        _twoFactorEnabled = s.TwoFactorEnabled;
        _sessions = new List<ActiveSession>(s.Sessions);
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally { _saving = false; }
    }

    private void PromptRevokeSession(ActiveSession session) => _sessionToRevoke = session;

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;

        _saving = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            ShowToast($"Session on {_sessionToRevoke.Device} revoked.");
            _sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to revoke session: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Appearance ──

    private void ApplyAppearance(AppearanceSettings a)
    {
        _appearanceTheme = a.Theme;
        _appearanceFontSize = a.FontSize;
        _appearanceLanguage = a.Language;
        _appearanceCompact = a.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appearanceTheme.ToLowerInvariant()} preview-font-{_appearanceFontSize.ToLowerInvariant()}";
        if (_appearanceCompact) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save appearance: {ex.Message}", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Toast ──

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

/* ── Layout ── */

.settings-dashboard {
    display: flex;
    min-height: 80vh;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.25rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
    font-weight: 600;
}

/* ── Toast ── */

.settings-toast {
    position: sticky;
    top: 0;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.65rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    font-size: 0.9rem;
    animation: slideDown 0.25s ease-out;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Avatar ── */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.25rem;
}

.avatar-preview img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: #adb5bd;
}

.avatar-url-display {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.avatar-url-display code {
    font-size: 0.8rem;
    word-break: break-all;
}

/* ── Toggle Rows ── */

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row .form-check-input {
    width: 2.5em;
    height: 1.25em;
}

/* ── Channel List ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    overflow: hidden;
}

.expandable-header {
