@rendermode InteractiveServer
@using sv_225bc71b5ead444abd531408973786ea.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
                    @_toastMessage
                    <button class="btn-close btn-close-sm ms-2" @onclick="() => _toastMessage = null"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@* ───── Profile Section ───── *@

@{ RenderFragment RenderProfile() =>
    @<section class="settings-section">
        <h3>Profile</h3>
        <p class="text-muted">Manage your public profile information.</p>
        <hr />

        <div class="avatar-area mb-4">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_profileDisplayName))
                {
                    <img src="@_profileAvatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">?</div>
                }
            </div>
            <div class="avatar-url-display">
                <small class="text-muted">Avatar URL:</small>
                <code>@_profileAvatarUrl</code>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_profileDisplayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_profileEmail" />
        </div>
        <div class="mb-3">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" @bind="_profileAvatarUrl" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </section>;
}

@* ───── Notifications Section ───── *@

@{ RenderFragment RenderNotifications() =>
    @<section class="settings-section">
        <h3>Notifications</h3>
        <p class="text-muted">Choose how you want to be notified.</p>
        <hr />

        <div class="toggle-row">
            <div>
                <strong>Email Notifications</strong>
                <div class="text-muted small">Receive notifications via email</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifEmail" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Push Notifications</strong>
                <div class="text-muted small">Receive push notifications in your browser</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifPush" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Weekly Digest</strong>
                <div class="text-muted small">Get a weekly summary of activity</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_notifWeeklyDigest" />
            </div>
        </div>

        <h5 class="mt-4 mb-3">Muted Channels</h5>
        @if (_allChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMuteChannel(ch, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                    </div>
                }
            </div>
        }

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>
    </section>;
}

@* ───── Security Section ───── *@

@{ RenderFragment RenderSecurity() =>
    @<section class="settings-section">
        <h3>Security</h3>
        <p class="text-muted">Manage your account security settings.</p>
        <hr />

        @* Change Password Panel *@
        <div class="expandable-panel mb-4">
            <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="expandable-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger py-2">@_passwordError</div>
                    }
                    <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Update Password
                    </button>
                </div>
            }
        </div>

        @* Two-Factor Auth *@
        <div class="toggle-row">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">
                    Status:
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" @bind="_twoFactorEnabled" />
            </div>
        </div>

        @if (_securitySettings?.LastPasswordChange is not null)
        {
            <p class="text-muted small mt-2">
                Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        @* Active Sessions *@
        <h5 class="mt-4 mb-3">Active Sessions</h5>
        @if (_sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }

        @* Revoke Confirmation Dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop-custom" @onclick="() => _sessionToRevoke = null"></div>
            <div class="confirm-dialog">
                <h5>Revoke Session</h5>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="d-flex gap-2 justify-content-end">
                    <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Revoke
                    </button>
                </div>
            </div>
        }
    </section>;
}

@* ───── Appearance Section ───── *@

@{ RenderFragment RenderAppearance() =>
    @<section class="settings-section">
        <h3>Appearance</h3>
        <p class="text-muted">Customize the look and feel of the application.</p>
        <hr />

        <div class="mb-4">
            <label class="form-label fw-bold">Theme</label>
