    color: #0d6efd;
    border-left-color: #0d6efd;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
    font-weight: 600;
}

/* ── Toast ── */

.settings-toast {
    position: sticky;
    top: 0;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.65rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    font-size: 0.9rem;
    animation: slideDown 0.25s ease-out;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Avatar ── */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.25rem;
}

.avatar-preview img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: #adb5bd;
}

.avatar-url-display {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.avatar-url-display code {
    font-size: 0.8rem;
    word-break: break-all;
}

/* ── Toggle Rows ── */

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row .form-check-input {
    width: 2.5em;
    height: 1.25em;
}

/* ── Channel List ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    overflow: hidden;
}

.expandable-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
    color: #212529;
}

.expandable-header:hover {
    background: #e9ecef;
}

.expandable-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* ── Confirm Dialog ── */

.modal-backdrop-custom {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1040;
}

.confirm-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
    width: 420px;
    max-width: 90vw;
    z-index: 1050;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.confirm-dialog h5 {
    margin-bottom: 0.75rem;
}

/* ── Live Preview ── */

.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-card {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin: 0.75rem 0;
}

.preview-card p {
    margin-bottom: 0;
}

.preview-btn {
    padding: 0.35rem 1rem;
    border-radius: 4px;
    border: none;
    font-weight: 500;
    cursor: default;
}

/* Theme: Light */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}
.preview-theme-light .preview-header {
    background: #f8f9fa;
}
.preview-theme-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

/* Theme: Dark */
.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
}
.preview-theme-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}
.preview-theme-dark .preview-card {
    border-color: #45475a;
    background: #313244;
}
.preview-theme-dark .preview-btn {
    background: #89b4fa;
