}
.preview-theme-system .preview-header {
    background: #e2e8f0;
}
.preview-theme-system .preview-btn {
    background: #6366f1;
    color: #fff;
}

/* Font sizes */
.preview-font-small {
    font-size: 0.8rem;
}
.preview-font-medium {
