+/* ── Layout ── */
+
+.settings-dashboard {
+    display: flex;
+    min-height: 80vh;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    overflow: hidden;
+    background: #fff;
+}
+
+/* ── Sidebar ── */
+
+.settings-sidebar {
+    width: 240px;
+    min-width: 240px;
+    background: #f8f9fa;
+    border-right: 1px solid #dee2e6;
+    padding: 1.25rem 0;
+}
+
+.sidebar-title {
+    padding: 0 1.25rem 1rem;
+    margin: 0;
+    font-weight: 600;
+    color: #495057;
+    text-transform: uppercase;
+    font-size: 0.75rem;
+    letter-spacing: 0.05em;
+}
+
+.settings-nav {
+    list-style: none;
+    padding: 0;
+    margin: 0;
+}
+
+.settings-nav-item {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.7rem 1.25rem;
+    cursor: pointer;
+    color: #495057;
+    font-weight: 500;
+    transition: background 0.15s, color 0.15s;
+    border-left: 3px solid transparent;
+}
+
+.settings-nav-item:hover {
+    background: #e9ecef;
+    color: #212529;
+}
+
+.settings-nav-item.active {
+    background: #e7f1ff;
+    color: #0d6efd;
+    border-left-color: #0d6efd;
+}
+
+.nav-icon {
+    font-size: 1.15rem;
+}
+
+/* ── Content Area ── */
+
+.settings-content {
+    flex: 1;
+    padding: 2rem;
+    position: relative;
+    overflow-y: auto;
+}
+
+.settings-section h3 {
+    margin-bottom: 0.25rem;
+    font-weight: 600;
+}
+
+/* ── Toast ── */
+
+.settings-toast {
+    position: sticky;
+    top: 0;
+    z-index: 10;
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.65rem 1rem;
+    border-radius: 6px;
+    margin-bottom: 1.25rem;
+    font-size: 0.9rem;
+    animation: slideDown 0.25s ease-out;
+}
+
+.toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+.toast-error {
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+}
+
+@keyframes slideDown {
+    from { opacity: 0; transform: translateY(-10px); }
+    to   { opacity: 1; transform: translateY(0); }
+}
+
+/* ── Avatar ── */
+
+.avatar-area {
+    display: flex;
+    align-items: center;
+    gap: 1.25rem;
+}
+
+.avatar-preview img {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 2px solid #dee2e6;
+}
+
+.avatar-placeholder {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    background: #e9ecef;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 2rem;
+    color: #adb5bd;
+}
+
+.avatar-url-display {
+    display: flex;
+    flex-direction: column;
+    gap: 0.15rem;
+}
+
+.avatar-url-display code {
+    font-size: 0.8rem;
+    word-break: break-all;
+}
+
